    page = await openWith(fresh());
    const writesAtOpen = store.sets;
    const domWritesAtOpen = domStorage.writes;
    await type(page, 'juan');
    await clickIf(page, tabNamed(page, 'Rentals'));
    await choose(page, 'PAID');
