        resetNet(200, answerForP(state));
        page = await globalThis.mountInteractive(root(), route);
        await page.settle();
        await clickIf(page, tabNamed(page, 'Overdue'));
        await press(page, numberButton(page, 2));
        const second = lookP(page);
