            !!tbl && ['data-table', 'stack-narrow', 'rental-bookings-table'].every((c) => tbl.classList.contains(c))
              && said(ths.map(text)) === said(HEADS)
              && ths.every((th, i) => (SIZED[i] ? th.classList.contains(SIZED[i]) : th.className === ''))
